<?php $admin_title='Gallery';include '_header.php';$rows=$pdo->query('SELECT * FROM gallery ORDER BY sort_order,id DESC')->fetchAll();?><div class="panel"><div class="panel-head"><div><h2>Gallery CMS</h2><small>Data-driven images used on the public gallery.</small></div><a class="btn btn-primary" href="gallery_form.php"><i class="fa-solid fa-plus"></i> Add Image</a></div><div class="table-wrap"><table><thead><tr><th>Image</th><th>Title</th><th>Category</th><th>Order</th><th>Status</th><th>Actions</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><img src="../<?=e($r['image_url'])?>" style="width:70px;height:50px;object-fit:cover;border-radius:10px"></td><td><?=e($r['title'])?></td><td><?=e($r['category'])?></td><td><?=$r['sort_order']?></td><td><?=e($r['status'])?></td><td><a class="btn" href="gallery_form.php?id=<?=$r['id']?>"><i class="fa-solid fa-pen"></i></a> <button class="btn btn-danger" data-delete-url="api/delete_gallery.php?id=<?=$r['id']?>"><i class="fa-solid fa-trash"></i></button></td></tr><?php endforeach;?></tbody></table></div></div><?php include '_footer.php';?>